    'anthropic-version: ${ANTHROPIC_VERSION}',
    '-H',
    'content-type: application/json',
    '-H',
    'accept: application/json',
    '--max-time',
    '600',
    '--connect-timeout',
    '30',
    '--fail-with-body',
    '--data-binary',
    '@-',
    BEDROCK_ENDPOINT,
  ]

  let mut child = match command.spawn {
    case Ok(value) -> value
    case Error(error) -> return Result.Error('Failed to spawn curl: ${error}')
  }

  let stdin = child.stdin := Option.None

  match stdin {
    case Some(mut handle) -> {
      match handle.write_string(body_str) {
        case Ok(_) -> {}
        case Error(error) -> {
          return Result.Error('Failed to write request body to curl: ${error}')
        }
      }

      match handle.close {
        case Ok(_) -> {}
        case Error(error) -> return Result.Error('Failed to close curl stdin: ${error}')
      }
    }
    case None -> return Result.Error('No stdin pipe available for curl')
  }

  let response_bytes = ByteArray.new
  let stdout = child.stdout := Option.None

  match stdout {
    case Some(mut handle) -> {
      match handle.read_all(response_bytes) {
        case Ok(_) -> {}
        case Error(error) -> {
          return Result.Error('Failed to read curl response: ${error}')
        }
      }
    }
    case None -> return Result.Error('No stdout pipe available for curl')
  }

  let status = match child.wait {
    case Ok(value) -> value
    case Error(error) -> return Result.Error('Failed to wait for curl: ${error}')
  }

  let response_str = response_bytes.into_string

  if status.success?.false? {
    return Result.Error('curl exited with code ${status.to_int}: ${response_str}')
  }

  extract_text_from_response(response_str)
}

type async Main {
  fn async main {
    let stdout = Stdout.new
    let stderr = Stderr.new

    let input_json = match read_stdin {
